with s as (
  insert into public.county_candidate_sources (state_code,county_name,election_date,election_name,source_url,source_published_on,coverage_status,coverage_note)
  values ('CA','Calaveras','2026-11-03','November 3, 2026 General Election','https://elections.calaverasgov.us/Portals/Elections/Documents/Candidates/qualified%20caniddate%20listcfmcfmr009_nominationlist.pdf','2026-09-02','source_complete','All 79 qualified candidate entries in the county list printed September 2, 2026; 21 in contests marked On Ballot: Yes, 58 in contests marked On Ballot: No.')
